package org.apache.commons.math.optimization.univariate;

import org.apache.commons.lang3.builder.EqualsBuilder;
import org.junit.*;
import static org.junit.Assert.*;

public class UnivariateRealPointValuePairSymflowerTest {
	@Test
	public void UnivariateRealPointValuePair1() {
		double point = 0.0D;
		double value = 0.0D;
		UnivariateRealPointValuePair expected = new UnivariateRealPointValuePair(0.0D, 0.0D);
		UnivariateRealPointValuePair actual = new UnivariateRealPointValuePair(point, value);

		assertTrue(EqualsBuilder.reflectionEquals(expected, actual, false, null, true));
	}

	@Test
	public void getPoint2() {
		UnivariateRealPointValuePair u = new UnivariateRealPointValuePair(0., 0.);
		double expected = 0.;
		double actual = u.getPoint();

		assertEquals(expected, actual, 0.0000001D);
	}

	@Test
	public void getValue3() {
		UnivariateRealPointValuePair u = new UnivariateRealPointValuePair(0., 0.);
		double expected = 0.;
		double actual = u.getValue();

		assertEquals(expected, actual, 0.0000001D);
	}
}
